from fastapi import APIRouter, Depends, HTTPException, Request, status
from fastapi_cache.decorator import cache

router = APIRouter(prefix="/documents")

def user_scoped_document_cache_key(func, namespace: str = "", request: Request = None, *args, **kwargs):
    user = kwargs.get("user")
    doc_id = kwargs.get("document_id", "")
    user_org_id = user.organization_id if user else "unauth"
    return f"{namespace}:{doc_id}:org_{user_org_id}"

@router.get("/{document_id}/preview-summary")
@cache(expire=1800, key_builder=user_scoped_document_cache_key)
async def get_document_preview_summary(
    document_id: str,
    doc_repo: DocumentRepository = Depends(get_document_repo),
    user: User = Depends(get_current_user)
):
    doc = await doc_repo.find_by_id(document_id)
    if not doc:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Document not found")

    if doc.organization_id != user.organization_id:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Unauthorized access to document")

    return {
        "document_id": document_id,
        "title": doc.title,
        "author": doc.author_name,
        "confidential_summary": doc.summary_snippet
    }
